package com.yihe.framework.ehr;
import java.util.*;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
@Service @SuppressWarnings("unchecked") public class ChronicRiskService {
 final EhrRepository db;final EhrService ehr;final EmployeeHealthArchiveService employees;final DigitalWorkerModelClient client;final DigitalWorkerSettings settings;
 static final List<String> FACTORS=Arrays.asList("hypertension","diabetes","lipids","obesity","cardiovascular");
 public ChronicRiskService(EhrRepository db,EhrService ehr,EmployeeHealthArchiveService employees,DigitalWorkerModelClient client){this.db=db;this.ehr=ehr;this.employees=employees;this.client=client;this.settings=new DigitalWorkerSettings(db);}
 void allow(EhrActor a,boolean write){require(!a.mobile,403,"个人端无慢性病风险评估管理权限");if(write)require(a.doctor,403,"慢性病风险评估操作需要医生权限");}
 Object canonical(Object o){if(o instanceof Map){Map<String,Object> m=new TreeMap<>();((Map<?,?>)o).forEach((k,v)->m.put(String.valueOf(k),canonical(v)));return m;}if(o instanceof List){List<Object> l=new ArrayList<>();for(Object v:(List<?>)o)l.add(canonical(v));return l;}return o;}
 String hash(Object o){return hex(digest(bytes(ehr.encode(canonical(o)))));}
 int year(Object raw){int y;try{y=Integer.parseInt(str(raw));}catch(Exception e){throw new EhrException(422,"请选择有效评估年度");}require(y>=2000&&y<=LocalDate.now().getYear()+1,422,"评估年度超出范围");return y;}
 Map<String,Object> defaults(){return map("keywords",map("hypertension",Arrays.asList("血压","高血压"),"diabetes",Arrays.asList("血糖","葡萄糖","糖化血红蛋白"),"lipids",Arrays.asList("总胆固醇","甘油三酯","低密度脂蛋白"),"obesity",Arrays.asList("BMI","体质指数","腰围"),"cardiovascular",Arrays.asList("心电图","心脑血管","家族史")),"instructions","结合原始体检指标、历年趋势、年龄性别、生活习惯及有来源病史，分别梳理高血压、糖尿病、血脂异常、肥胖、心脑血管的慢性病风险线索，逐项注明日期、原值、单位、参考范围与页码；资料不足明确待核实。","method","clinician_confirmed");}
 public Map<String,Object> rules(EhrActor a){allow(a,false);Map<String,Object> row=db.one("SELECT * FROM a_chronic_risk_rules WHERE scope_code=? AND data_mode=?",a.scope,a.mode);return map("document",row==null?defaults():ehr.decode(row.get("rules_json")),"version",row==null?0:row.get("row_version"),"updatedAt",row==null?null:row.get("updated_at"),"updatedBy",row==null?null:row.get("updated_by"),"canConfigure",a.doctor);}
 @Transactional public Object saveRules(EhrActor a,Map<String,Object> b){allow(a,true);Map<String,Object> doc=map("method","clinician_confirmed");Object raw=b.get("keywords");require(raw instanceof Map&&((Map<?,?>)raw).keySet().equals(new HashSet<>(FACTORS)),422,"需提供五类指标关联关键词");Map<String,Object> keywords=new LinkedHashMap<>();for(String f:FACTORS){Object list=((Map<?,?>)raw).get(f);require(list instanceof List&&((List<?>)list).size()>=1&&((List<?>)list).size()<=20,422,"每类应有1至20个关键词");List<String> words=new ArrayList<>();for(Object v:(List<?>)list){require(v instanceof String&&!str(v).trim().isEmpty()&&str(v).length()<=30,422,"关键词长度应为1至30字");words.add(str(v).trim());}keywords.put(f,words);}String instructions=text(b,"instructions").trim();require(!instructions.isEmpty()&&instructions.length()<=2000,422,"评估要求应为1至2000字");doc.put("keywords",keywords);doc.put("instructions",instructions);db.exec("INSERT IGNORE INTO a_chronic_risk_rules(scope_code,data_mode,rules_json,row_version,updated_by,updated_at) VALUES(?,?,?,0,?,UTC_TIMESTAMP(6))",a.scope,a.mode,ehr.encode(defaults()),a.user);Map<String,Object> old=db.one("SELECT row_version FROM a_chronic_risk_rules WHERE scope_code=? AND data_mode=? FOR UPDATE",a.scope,a.mode);require(b.get("version") instanceof Number&&num(b.get("version"))==num(old.get("row_version")),409,"规则已更新，请刷新后再保存");db.exec("UPDATE a_chronic_risk_rules SET rules_json=?,row_version=row_version+1,updated_by=?,updated_at=UTC_TIMESTAMP(6) WHERE scope_code=? AND data_mode=?",ehr.encode(doc),a.user,a.scope,a.mode);ehr.audit(a,null,null,null,"chronic_risk_rules_saved","更新指标关联关键词和分析要求；风险等级仍须医生核定");return rules(a);}
 Map<String,Object> source(EhrActor a,String record){Map<String,Object> p=employees.detail(a,record);p.remove("logs");p.remove("assessments");p.remove("serviceTasks");p.remove("followups");p.remove("publishedReports");p.put("occupationalFields",db.all("SELECT o.field_key fieldKey,o.original_field_name label,o.value_raw value,o.review_status reviewStatus,o.report_id reportId,o.revision,e.source_file_id sourceId,e.page_number page FROM a_occupational_profiles o JOIN a_health_reports h ON h.report_id=o.report_id AND h.revision=o.revision JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision LEFT JOIN a_report_evidence e ON e.evidence_id=o.evidence_id AND e.report_id=o.report_id AND e.revision=o.revision WHERE h.record_id=? AND h.scope_code=? AND h.data_mode=? AND o.scope_code=? AND o.data_mode=? ORDER BY h.report_id,o.field_key,o.profile_id",record,a.scope,a.mode,a.scope,a.mode));return new AssessmentRuleRuntime(db,ehr).attach(a,"chronic",p);}
 String sourceHash(Map<String,Object> p){Map<String,Object> person=new TreeMap<>();for(String k:Arrays.asList("id","name","code","sex","birth","age","org","team","job","exposure","rowVersion"))person.put(k,p.get(k));List<Object> rs=new ArrayList<>();for(Object v:(List<?>)p.get("reports")){Map<?,?> r=(Map<?,?>)v;rs.add(map("id",r.get("id"),"revision",r.get("revision"),"etag",r.get("etag")));}Map<String,Object> signature=map("person",person,"reports",rs,"occupationalFields",p.get("occupationalFields"));if(p.containsKey("assessmentRules"))signature.put("assessmentRules",p.get("assessmentRules"));return hash(signature);}
 String manifest(EhrActor a,String record){Map<String,Object> m=db.one("SELECT GROUP_CONCAT(CONCAT(h.report_id,':',h.revision) ORDER BY h.report_id SEPARATOR ',') manifest FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision WHERE h.scope_code=? AND h.data_mode=? AND h.record_id=?",a.scope,a.mode,record);return str(m.get("manifest"));}
 List<String> exposures(String text,Map<String,Object> rules){List<String> factors=new ArrayList<>();Map<String,Object> keywords=(Map<String,Object>)rules.get("keywords");for(String f:FACTORS)for(Object word:(List<?>)keywords.get(f))if(text.contains(str(word))){factors.add(f);break;}return factors;}
 String state(Map<String,Object> r){if(r.get("taskId")==null)return "not_started";if(Boolean.TRUE.equals(r.get("stale")))return "stale";if("confirmed".equals(r.get("reviewState")))return "confirmed";if("completed".equals(r.get("aiState")))return "pending_review";return str(r.get("aiState"));}
 List<Map<String,Object>> rows(EhrActor a,int year){List<Map<String,Object>> rows=db.all("SELECT r.record_id id,p.employee_name name,p.employee_no code,p.organization_name organization,p.team_name team,p.position_name job,p.exposure_history exposure,p.row_version profileVersion,t.task_id taskId,t.assessment_year assessmentYear,t.ai_state aiState,t.review_state reviewState,t.risk_level storedRisk,t.domain_json domainJson,t.profile_version sourceVersion,t.report_manifest sourceManifest,t.rules_version rulesVersion,JSON_UNQUOTE(JSON_EXTRACT(t.source_json,'$.assessmentRuleDigest')) registryDigest,t.reviewed_at reviewedAt,t.created_at createdAt,t.row_version version,(SELECT GROUP_CONCAT(CONCAT(h.report_id,':',h.revision) ORDER BY h.report_id SEPARATOR ',') FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision WHERE h.scope_code=r.scope_code AND h.data_mode=r.data_mode AND h.record_id=r.record_id) currentManifest FROM a_health_records r JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode LEFT JOIN a_chronic_risk_tasks t ON t.scope_code=r.scope_code AND t.data_mode=r.data_mode AND t.record_id=r.record_id AND (?=0 OR t.assessment_year=?) AND t.task_id=(SELECT t2.task_id FROM a_chronic_risk_tasks t2 WHERE t2.scope_code=r.scope_code AND t2.data_mode=r.data_mode AND t2.record_id=r.record_id AND (?=0 OR t2.assessment_year=?) ORDER BY t2.created_at DESC,t2.task_id DESC LIMIT 1) WHERE r.scope_code=? AND r.data_mode=? AND p.deleted_at IS NULL ORDER BY p.created_at,r.record_id",year,year,year,year,a.scope,a.mode);Map<String,Object> rule=rules(a);String registryDigest=new AssessmentRuleRuntime(db,ehr).digest(a,"chronic");for(Map<String,Object> r:rows){boolean stale=r.get("taskId")!=null&&(num(r.get("sourceVersion"))!=num(r.get("profileVersion"))||!str(r.get("sourceManifest")).equals(str(r.get("currentManifest")))||num(r.get("rulesVersion"))!=num(rule.get("version"))||!str(r.get("registryDigest")).equals(registryDigest));r.put("stale",stale);boolean confirmed=!stale&&"confirmed".equals(r.get("reviewState"));r.put("riskLevel",confirmed?r.get("storedRisk"):"unknown");r.put("domains",confirmed?ehr.decode(r.get("domainJson")):new HashMap<>());r.put("exposureFactors",exposures(str(r.get("exposure")),(Map<String,Object>)rule.get("document")));r.put("state",state(r));for(String k:Arrays.asList("domainJson","sourceVersion","profileVersion","sourceManifest","currentManifest","storedRisk"))r.remove(k);}return rows;}
 public Map<String,Object> list(EhrActor a,Map<String,String> q){allow(a,false);List<Map<String,Object>> all=rows(a,0),filtered=new ArrayList<>();Set<String> orgs=new TreeSet<>(),teams=new TreeSet<>(),jobs=new TreeSet<>();String period=q.getOrDefault("period","12");require(Arrays.asList("12","24","all").contains(period),422,"请选择有效时间范围");LocalDate cutoff=period.equals("all")?LocalDate.of(1900,1,1):LocalDate.now().minusMonths(Integer.parseInt(period));String type=q.getOrDefault("type","");require(type.isEmpty()||FACTORS.contains(type),422,"风险类别无效");for(Map<String,Object> r:all){orgs.add(str(r.get("organization")));teams.add(str(r.get("team")));jobs.add(str(r.get("job")));String search=q.getOrDefault("search","").trim();boolean match=search.isEmpty()||str(r.get("name")).contains(search)||str(r.get("code")).contains(search);for(String k:Arrays.asList("organization","team","job","riskLevel","state")){String v=q.getOrDefault(k,"");if(!v.isEmpty()&&!(k.equals("riskLevel")&&v.equals("elevated")?Arrays.asList("high","critical").contains(r.get(k)):v.equals(str(r.get(k)))))match=false;}if(!type.isEmpty()&&(!((Map<?,?>)r.get("domains")).containsKey(type)||"unknown".equals(((Map<?,?>)((Map<?,?>)r.get("domains")).get(type)).get("level"))))match=false;String time=str(r.get("reviewedAt"));if(time.length()>=10&&LocalDate.parse(time.substring(0,10)).isBefore(cutoff))match=false;if(match)filtered.add(r);}
 Map<String,Object> counts=map("total",filtered.size(),"pending",0,"confirmed",0,"processing",0,"low",0,"medium",0,"high",0,"critical",0,"unknown",0,"todayAlerts",0),categories=new LinkedHashMap<>();for(String f:FACTORS)categories.put(f,map("total",0,"high",0,"medium",0,"monthlyChange",null));Set<String> allowed=new HashSet<>();for(Map<String,Object> r:filtered){allowed.add(str(r.get("id")));if("confirmed".equals(r.get("state")))counts.put("confirmed",num(counts.get("confirmed"))+1);else counts.put("pending",num(counts.get("pending"))+1);if(Arrays.asList("queued","running").contains(r.get("state")))counts.put("processing",num(counts.get("processing"))+1);String risk=str(r.get("riskLevel"));counts.put(risk,num(counts.get(risk))+1);Map<String,Object> domains=(Map<String,Object>)r.get("domains");for(String f:FACTORS){Map<String,Object>d=(Map<String,Object>)domains.get(f),c=(Map<String,Object>)categories.get(f);String level=d==null?"unknown":str(d.get("level"));if(!level.equals("unknown"))c.put("total",num(c.get("total"))+1);if(Arrays.asList("high","critical").contains(level))c.put("high",num(c.get("high"))+1);if(level.equals("medium"))c.put("medium",num(c.get("medium"))+1);}r.put("abnormalities","");}
 List<Map<String,Object>> history=db.all("SELECT t.record_id recordId,t.risk_level riskLevel,t.domain_json domains,CAST(DATE(CONVERT_TZ(t.reviewed_at,'+00:00','+08:00')) AS CHAR) reviewDay,t.task_id id FROM a_chronic_risk_tasks t JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE t.scope_code=? AND t.data_mode=? AND p.deleted_at IS NULL AND t.review_state='confirmed' ORDER BY t.reviewed_at,t.task_id",a.scope,a.mode);Map<String,Map<String,Object>> monthOld=new HashMap<>();LocalDate today=LocalDate.now();for(Map<String,Object> h:history){if(!allowed.contains(str(h.get("recordId"))))continue;if(str(h.get("reviewDay")).equals(today.toString())&&Arrays.asList("high","critical").contains(h.get("riskLevel"))){for(Map<String,Object> r:filtered)if(r.get("id").equals(h.get("recordId"))&&r.get("taskId").equals(h.get("id"))&&r.get("state").equals("confirmed"))counts.put("todayAlerts",num(counts.get("todayAlerts"))+1);}if(LocalDate.parse(str(h.get("reviewDay"))).isBefore(today.withDayOfMonth(1)))monthOld.put(str(h.get("recordId")),h);}
 for(String f:FACTORS){int old=0;for(Map<String,Object> h:monthOld.values()){Map<?,?>ds=(Map<?,?>)ehr.decode(h.get("domains"));Map<?,?> v=(Map<?,?>)ds.get(f);if(v!=null&&Arrays.asList("high","critical").contains(v.get("level")))old++;}Map<String,Object> c=(Map<String,Object>)categories.get(f);if(old>0)c.put("monthlyChange",Math.round((num(c.get("high"))-old)*1000.0/old)/10.0);}
 List<Object> trend=new ArrayList<>();for(int i=11;i>=0;i--){LocalDate month=today.withDayOfMonth(1).minusMonths(i),end=month.plusMonths(1);Map<String,Map<String,Object>> last=new HashMap<>();for(Map<String,Object> h:history)if(allowed.contains(str(h.get("recordId")))&&LocalDate.parse(str(h.get("reviewDay"))).isBefore(end))last.put(str(h.get("recordId")),h);int high=0;for(Map<String,Object> h:last.values())if(Arrays.asList("high","critical").contains(h.get("riskLevel")))high++;trend.add(map("month",month.toString().substring(0,7),"count",high));}
 Map<String,String> abnormal=new HashMap<>();for(Map<String,Object> r:db.all("SELECT h.record_id recordId,GROUP_CONCAT(CONCAT(i.original_field_name,' ',COALESCE(i.result_raw,''),CASE WHEN i.unit_raw IS NULL THEN '' ELSE CONCAT(' ',i.unit_raw) END) ORDER BY i.ordinal SEPARATOR '；') abnormalities FROM a_health_reports h JOIN a_report_series s ON s.report_id=h.report_id AND s.current_revision=h.revision JOIN a_health_items i ON i.report_id=h.report_id AND i.revision=h.revision WHERE h.scope_code=? AND h.data_mode=? AND h.report_id=(SELECT h2.report_id FROM a_health_reports h2 JOIN a_report_series s2 ON s2.report_id=h2.report_id AND s2.current_revision=h2.revision WHERE h2.scope_code=h.scope_code AND h2.data_mode=h.data_mode AND h2.record_id=h.record_id ORDER BY h2.exam_date_verified DESC,h2.created_at DESC,h2.report_id DESC LIMIT 1) AND "+AiExamService.abnormal()+" GROUP BY h.record_id",a.scope,a.mode))abnormal.put(str(r.get("recordId")),str(r.get("abnormalities")));for(Map<String,Object>r:filtered)r.put("abnormalities",abnormal.getOrDefault(str(r.get("id")),""));
 List<Map<String,Object>> top=new ArrayList<>();for(Map<String,Object>r:filtered)if(Arrays.asList("high","critical").contains(r.get("riskLevel")))top.add(r);top.sort((x,y)->{int c=Boolean.compare("critical".equals(y.get("riskLevel")),"critical".equals(x.get("riskLevel")));return c!=0?c:str(y.get("reviewedAt")).compareTo(str(x.get("reviewedAt")));});int page=bounded(q.get("page"),1,1,100000),limit=bounded(q.get("limit"),10,1,100),from=Math.min(filtered.size(),(page-1)*limit);return map("items",filtered.subList(from,Math.min(from+limit,filtered.size())),"total",filtered.size(),"page",page,"limit",limit,"counts",counts,"categories",categories,"trend",trend,"top",top.subList(0,Math.min(5,top.size())),"organizations",orgs,"teams",teams,"jobs",jobs,"canReview",a.doctor,"candidateOnly",ehr.candidateOnly,"period",period,"assessmentYear",today.getYear());}

 Map<String,Object> job(EhrActor a,String id,boolean lock){Map<String,Object> row=db.one("SELECT * FROM a_chronic_risk_tasks WHERE task_id=? AND scope_code=? AND data_mode=?",id,a.scope,a.mode);require(row!=null,404,"慢性病风险任务不存在或无权限");ehr.profile(a,str(row.get("record_id")),lock);if(lock)row=db.one("SELECT * FROM a_chronic_risk_tasks WHERE task_id=? AND scope_code=? AND data_mode=? FOR UPDATE",id,a.scope,a.mode);return row;}
 public Map<String,Object> detail(EhrActor a,String record,int year,String task){allow(a,false);Map<String,Object> facts=source(a,record),t=task==null||task.isEmpty()?db.one("SELECT * FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 1",a.scope,a.mode,record,year):job(a,task,false);require(t==null||record.equals(t.get("record_id"))&&num(t.get("assessment_year"))==year,404,"任务不属于当前职工和年度");Map<String,Object> current=rules(a);return map("source",facts,"sourceDigest",sourceHash(facts),"job",t,"sourceChanged",t!=null&&!sourceHash(facts).equals(t.get("source_digest")),"rulesChanged",t!=null&&num(t.get("rules_version"))!=num(current.get("version")),"history",db.all("SELECT task_id id,ai_state aiState,review_state reviewState,risk_level riskLevel,created_at createdAt,reviewed_at reviewedAt FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 30",a.scope,a.mode,record,year),"canReview",a.doctor,"candidateOnly",ehr.candidateOnly);}
 @Transactional public Map<String,Object> enqueue(EhrActor a,Map<String,Object> b){allow(a,true);require(Boolean.TRUE.equals(client.status().get("configured")),503,"独立AI服务尚未配置");int y=year(b.get("year"));String key=text(b,"requestKey");require(key.matches("[0-9a-fA-F-]{36}"),422,"请求键无效");Object raw=b.get("records");require(raw instanceof List&&!((List<?>)raw).isEmpty()&&((List<?>)raw).size()<=20,422,"每批请选择1至20名职工");String payload=hash(b);Map<String,Object> policy=settings.lock(a,"assess");List<Map<String,Object>> old=db.all("SELECT batch_id,payload_digest FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND request_key=?",a.scope,a.mode,key);if(!old.isEmpty()){require(payload.equals(old.get(0).get("payload_digest")),409,"请求键已用于不同内容");return map("batchId",old.get(0).get("batch_id"),"count",old.size(),"replayed",true);}settings.requireAi(policy);settings.admit(a,"assess","assessment",policy);require(db.count("SELECT COUNT(*) FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND ai_state IN ('queued','running')",a.scope,a.mode)+((List<?>)raw).size()<=num(policy.get("maxActiveTasks")),409,"慢性病风险任务队列已达配置上限");Set<String> ids=new TreeSet<>();for(Object v:(List<?>)raw){require(v instanceof String&&str(v).matches("[0-9a-fA-F-]{36}")&&ids.add(str(v)),422,"职工标识无效或重复");}Map<String,Object> rule=rules(a);String batch=id();for(String record:ids){ehr.profile(a,record,true);require(db.count("SELECT COUNT(*) FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? AND ai_state IN ('queued','running')",a.scope,a.mode,record,y)==0,409,"所选职工已有本年度分析排队或运行");Map<String,Object> facts=source(a,record);List<?> reports=(List<?>)facts.get("reports");require(!reports.isEmpty()&&reports.stream().anyMatch(v->!((List<?>)((Map<?,?>)v).get("items")).isEmpty()),422,"所选职工缺少结构化体检报告，请先上传并识别");require(ehr.encode(facts).length()<=1800000,422,"关联资料过多，请整理后再评估");String task=id();db.insert("a_chronic_risk_tasks",map("task_id",task,"batch_id",batch,"scope_code",a.scope,"data_mode",a.mode,"record_id",record,"assessment_year",y,"request_key",key,"payload_digest",payload,"source_digest",sourceHash(facts),"source_json",ehr.encode(facts),"profile_version",facts.get("rowVersion"),"report_manifest",manifest(a,record),"rules_version",rule.get("version"),"rules_json",ehr.encode(rule.get("document")),"ai_state","queued","requested_by",a.user,"created_at",now()));ehr.audit(a,record,null,null,"chronic_risk_enqueued","已排队慢性病风险辅助分析，年度"+y+"；不自动确认风险");}return map("batchId",batch,"count",ids.size());}
 @Transactional(isolation=Isolation.READ_COMMITTED) public Map<String,Object> claim(String mode){db.exec("UPDATE a_chronic_risk_tasks SET ai_state='failed',error_code='AI_LEASE_EXPIRED',finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE data_mode=? AND ai_state='running' AND lease_until<UTC_TIMESTAMP(6)",mode);Map<String,Object> t=db.one("SELECT * FROM a_chronic_risk_tasks WHERE data_mode=? AND ai_state='queued' ORDER BY created_at,task_id LIMIT 1 FOR UPDATE",mode);if(t==null)return null;db.exec("UPDATE a_chronic_risk_tasks SET ai_state='running',lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 20 MINUTE),row_version=row_version+1 WHERE task_id=?",t.get("task_id"));t.put("row_version",num(t.get("row_version"))+1);return t;}
 EhrActor workerActor(Map<String,Object> t){String scope=str(t.get("scope_code"));require(scope.startsWith("org:")&&db.count("SELECT COUNT(*) FROM yh_user_reginfo WHERE user_code=? AND lock_flag=2 AND User_Type=4 AND CONCAT('org:',Org_Code)=?",t.get("requested_by"),scope)>0,403,"AI_ACCESS_REVOKED");return new EhrActor(str(t.get("requested_by")),scope.substring(4),str(t.get("data_mode")),true,false);}
 void verify(EhrActor a,Map<String,Object> t){require(sourceHash(source(a,str(t.get("record_id")))).equals(t.get("source_digest")),409,"AI_SOURCE_CHANGED");require(num(rules(a).get("version"))==num(t.get("rules_version")),409,"AI_RULES_CHANGED");}
 public Map<String,Object> modelInput(Map<String,Object> t){EhrActor a=workerActor(t);verify(a,t);settings.requireAi(settings.get(a,"assess"));Map<String,Object> rules=(Map<String,Object>)ehr.decode(t.get("rules_json"));return map("worker_id","assess","task_type","chronic_risk_assessment","title","慢性病风险辅助评估 · "+t.get("assessment_year"),"instructions",rules.get("instructions"),"archive_context",map("assessmentYear",t.get("assessment_year"),"person",ehr.decode(t.get("source_json")),"rules",rules));}
 @Transactional public void finish(Map<String,Object> claimed,String output,String failure){String error=failure;try{EhrActor a=workerActor(claimed);ehr.profile(a,str(claimed.get("record_id")),true);verify(a,claimed);settings.requireAi(settings.get(a,"assess"));}catch(EhrException e){error=e.getMessage().matches("[A-Z0-9_]{1,80}")?e.getMessage():"AI_ACCESS_OR_SOURCE_UNAVAILABLE";}Map<String,Object> t=db.one("SELECT * FROM a_chronic_risk_tasks WHERE task_id=? FOR UPDATE",claimed.get("task_id"));if(t==null||!"running".equals(t.get("ai_state"))||num(t.get("row_version"))!=num(claimed.get("row_version")))return;boolean ok=error==null&&output!=null&&!output.trim().isEmpty();db.exec("UPDATE a_chronic_risk_tasks SET ai_state=?,output_text=?,error_code=?,finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE task_id=?",ok?"completed":"failed",ok?output:null,ok?null:error==null?"AI_EMPTY":error,t.get("task_id"));}
 public List<Map<String,Object>> tasks(EhrActor a){allow(a,false);return db.all("SELECT t.batch_id batchId,t.task_id id,t.record_id recordId,t.assessment_year year,t.ai_state aiState,t.review_state reviewState,t.error_code errorCode,t.created_at createdAt,t.row_version version,p.employee_name name,p.employee_no code FROM a_chronic_risk_tasks t JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode WHERE t.scope_code=? AND t.data_mode=? AND p.deleted_at IS NULL ORDER BY t.created_at DESC,t.task_id DESC LIMIT 100",a.scope,a.mode);}
 @Transactional public Object action(EhrActor a,String task,Map<String,Object> b){allow(a,true);Map<String,Object> t=job(a,task,true);String key=text(b,"requestKey"),action=text(b,"action"),note=text(b,"note").trim(),payload=hash(b);require(key.matches("[0-9a-fA-F-]{36}")&&Arrays.asList("cancel","review").contains(action),422,"操作或请求键无效");Map<String,Object> old=db.one("SELECT payload_digest FROM a_chronic_risk_events WHERE task_id=? AND request_key=?",task,key);if(old!=null){require(payload.equals(old.get("payload_digest")),409,"操作键内容冲突");return map("replayed",true);}require(!note.isEmpty()&&note.length()<=3000,422,"请填写处理依据，最多3000字");require(b.get("version") instanceof Number&&num(b.get("version"))==num(t.get("row_version")),409,"任务版本已更新，请刷新");String record=str(t.get("record_id"));if(action.equals("cancel")){require(Arrays.asList("queued","running").contains(t.get("ai_state")),409,"当前任务不能取消");db.exec("UPDATE a_chronic_risk_tasks SET ai_state='cancelled',finished_at=UTC_TIMESTAMP(6),lease_until=NULL,row_version=row_version+1 WHERE task_id=?",task);}else{require(!ehr.candidateOnly,403,"当前环境不允许审核确认");require("completed".equals(t.get("ai_state"))&&"pending".equals(t.get("review_state")),409,"请先完成AI辅助分析或重新发起评估");require(task.equals(db.one("SELECT task_id FROM a_chronic_risk_tasks WHERE scope_code=? AND data_mode=? AND record_id=? AND assessment_year=? ORDER BY created_at DESC,task_id DESC LIMIT 1",a.scope,a.mode,record,t.get("assessment_year")).get("task_id")),409,"请审核本年度最新任务");verify(a,t);require(Boolean.TRUE.equals(b.get("identityVerified"))&&Boolean.TRUE.equals(b.get("sourceVerified")),422,"请核对职工身份、报告原件及生活习惯与病史资料");String risk=text(b,"riskLevel");require(Arrays.asList("low","medium","high","critical").contains(risk),422,"请由医生核定综合慢性病风险");Object raw=b.get("domains");require(raw instanceof Map&&((Map<?,?>)raw).keySet().equals(new HashSet<>(FACTORS)),422,"请核对五类分项风险");Map<String,Object> domains=new LinkedHashMap<>();for(String f:FACTORS){Object v=((Map<?,?>)raw).get(f);require(v instanceof Map,422,"风险格式无效");String level=str(((Map<?,?>)v).get("level")),basis=str(((Map<?,?>)v).get("basis")).trim();require(Arrays.asList("unknown","low","medium","high","critical").contains(level)&&basis.length()<=1500&&(level.equals("unknown")||!basis.isEmpty()),422,"分项风险需明确等级与依据");domains.put(f,map("level",level,"basis",basis));}Map<String,Object> facts=source(a,record);for(Object value:(List<?>)facts.get("reports"))require(Boolean.TRUE.equals(((Map<?,?>)value).get("published")),422,"请先在档案审核与归档中完成关联报告归档");Map<String,Object> profile=ehr.profile(a,record,false);String assessment=id();db.insert("a_health_risk_assessments",ehr.scoped(a,"assessment_id",assessment,"record_id",record,"employee_id",profile.get("employee_id"),"assessment_time",now(),"risk_level",risk,"assessment_type","ai_assisted","rule_version","chronic-clinician-v1","assessment_status","confirmed","reviewer_ref",bytes(a.user),"reviewed_at",now()));for(Object value:(List<?>)facts.get("reports")){Map<?,?> r=(Map<?,?>)value;db.insert("a_health_risk_report_sources",ehr.scoped(a,"record_id",record,"assessment_id",assessment,"report_id",r.get("id"),"revision",r.get("revision")));}db.exec("UPDATE a_chronic_risk_tasks SET review_state='confirmed',risk_level=?,domain_json=?,reviewer=?,review_note=?,reviewed_at=UTC_TIMESTAMP(6),assessment_id=?,row_version=row_version+1 WHERE task_id=?",risk,ehr.encode(domains),a.user,note,assessment,task);}db.insert("a_chronic_risk_events",map("event_id",id(),"task_id",task,"actor",a.user,"action",action,"note",note,"request_key",key,"payload_digest",payload,"created_at",now()));ehr.audit(a,record,null,null,"chronic_risk_"+action,note);return map("id",task,"action",action);}
}
